package com.bank.maint;

import java.util.ArrayList;
import java.util.List;
import java.util.logging.Logger;

// Tracks all data files, the current version, and which files each version referenced.
class DeltaStorage {
    private static final Logger log = Logger.getLogger(DeltaStorage.class.getName());

    final List<DataFile> files = new ArrayList<>();
    int currentVersion = 0;

    void write(DataFile f) {
        files.add(f);
        log.fine(() -> "Wrote file " + f.id + " (version " + f.writtenInVersion + ")");
    }

    long smallFileCount() { return files.stream().filter(f -> f.referencedByCurrent).count(); }
    long unreferencedOlderThan(long hours) {
        return files.stream().filter(f -> !f.referencedByCurrent && f.ageHours > hours).count();
    }

    List<DataFile> referenced() { return files.stream().filter(f -> f.referencedByCurrent).toList(); }
}
