package com.bank.maint;

import java.util.List;
import java.util.logging.Logger;

// OPTIMIZE: compact small referenced files into one large file; ZORDER enables skipping.
class Optimizer {
    private static final Logger log = Logger.getLogger(Optimizer.class.getName());

    void optimize(DeltaStorage storage, boolean zorder) {
        List<DataFile> small = storage.referenced();
        log.info(() -> "OPTIMIZE compacting " + small.size() + " small files into 1 large file");

        // Old small files become UNREFERENCED (kept as history until VACUUM).
        int newVersion = ++storage.currentVersion;
        int minKey = small.stream().mapToInt(f -> f.minKey).min().orElse(0);
        int maxKey = small.stream().mapToInt(f -> f.maxKey).max().orElse(0);
        for (DataFile f : small) f.referencedByCurrent = false;

        // The compacted file. If zordered, data is sorted so sub-ranges skip cleanly.
        DataFile big = new DataFile("compacted-v" + newVersion, newVersion, true, 0, minKey, maxKey);
        storage.write(big);
        if (zorder) {
            log.info(() -> "ZORDER BY (trade_date, symbol) applied — per-file min/max now enable data skipping");
        }
        log.info(() -> "OPTIMIZE done. Old small files are now UNREFERENCED history (storage temporarily grows)");
    }

    // Simulate a filtered read using min/max skipping on the referenced files.
    int filesScannedForFilter(DeltaStorage storage, int filterKey) {
        int scanned = 0;
        for (DataFile f : storage.referenced()) {
            if (filterKey >= f.minKey && filterKey <= f.maxKey) scanned++;
        }
        final int s = scanned;
        log.info(() -> "Query filter key=" + filterKey + " scanned " + s + " file(s) (skipped the rest)");
        return scanned;
    }
}
