package com.bank.maint;

import java.util.Iterator;
import java.util.logging.Logger;

// VACUUM: delete unreferenced files older than retention. Refuses below the safety window.
class Vacuumer {
    private static final Logger log = Logger.getLogger(Vacuumer.class.getName());

    private final long defaultRetentionHours;

    Vacuumer(long defaultRetentionHours) { this.defaultRetentionHours = defaultRetentionHours; }

    void vacuum(DeltaStorage storage, long retentionHours, boolean overrideSafety) {
        if (retentionHours < defaultRetentionHours && !overrideSafety) {
            log.severe(() -> "VACUUM REFUSED: retention " + retentionHours + "h < safety "
                    + defaultRetentionHours + "h. Vacuuming below retention would DELETE files that "
                    + "recent versions reference → breaks time travel.");
            return;
        }
        if (retentionHours < defaultRetentionHours) {
            log.warning(() -> "Safety check OVERRIDDEN — this is a known foot-gun and can break time travel/readers");
        }
        int removed = 0;
        Iterator<DataFile> it = storage.files.iterator();
        while (it.hasNext()) {
            DataFile f = it.next();
            if (!f.referencedByCurrent && f.ageHours > retentionHours) { it.remove(); removed++; }
        }
        int r = removed;
        log.info(() -> "VACUUM removed " + r + " old unreferenced files (reclaimed storage)");
    }

    // A time-travel read of an old version fails if its files were vacuumed away.
    boolean canTimeTravelTo(DeltaStorage storage, int version) {
        boolean ok = storage.files.stream().anyMatch(f -> f.writtenInVersion == version);
        log.info(() -> "Time travel to version " + version + " → " + (ok ? "OK (files present)" : "FAILED (files vacuumed)"));
        return ok;
    }
}
