package com.bank.maint;

import java.util.logging.Logger;

public class MaintenanceDemo {
    private static final Logger log = Logger.getLogger(MaintenanceDemo.class.getName());

    public static void main(String[] args) {
        DeltaStorage storage = new DeltaStorage();

        // Streaming wrote 6 tiny files (version 0), each covering a key sub-range.
        for (int i = 0; i < 6; i++) {
            storage.write(new DataFile("small-" + i, 0, true, 800 /*~33 days old*/, i * 10, i * 10 + 9));
        }
        log.info(() -> "Before OPTIMIZE: " + storage.smallFileCount() + " small referenced files");

        // OPTIMIZE with ZORDER.
        Optimizer optimizer = new Optimizer();
        optimizer.optimize(storage, true);
        log.info(() -> "After OPTIMIZE: " + storage.smallFileCount() + " referenced file(s), "
                + storage.files.size() + " total files on storage");

        // Z-ordered read skips files by min/max.
        optimizer.filesScannedForFilter(storage, 25);

        // VACUUM: safe below default? Audit needs 30 days = 720h retention.
        Vacuumer vacuumer = new Vacuumer(168); // 7-day default safety

        // Unsafe attempt: retention 1 hour → refused (would break time travel).
        vacuumer.vacuum(storage, 1, false);

        // Safe vacuum at 720h retention: old small files (800h) are NOT older than 720h? They are 800>720 → removed.
        vacuumer.vacuum(storage, 720, false);

        // Time travel to version 0 now fails because its small files were vacuumed.
        vacuumer.canTimeTravelTo(storage, 0);
        vacuumer.canTimeTravelTo(storage, storage.currentVersion);
    }
}
